  if width==390:page.screenshot(path='work/choice-buyer-390.png',full_page=True)
  assert page.evaluate('document.documentElement.scrollWidth<=innerWidth') and not errors,errors;c.close();print(f'{width}x{height} nickname-only typing, repayment, product selection, unknown/known/free listing, buyer counteroffer PASS',flush=True)
